/** Per-question "学習中" status and spaced-review bookkeeping (localStorage). */
import type { Lang, ReviewInfo, Sentence, StudySettings } from "@/types";

/** One tracked question's study state, keyed by category + q. */
export interface StudyItem {
  category: string;
  /** Sentence display text (意味). */
  disp: string;
  /** Typing target / romaji (入力) — identity within a category. */
  q: string;
  /** Reading in hiragana; absent for English and for items saved before this field. */
  kana?: string;
  lang: Lang;
  /** Stable sentence identity; may be absent on items saved before UUIDs. */
  uuid?: string;
  /** Whether the item is currently in the review rotation. */
  learning: boolean;
  /** How many times it has already been re-presented for review. */
  reviewsDone: number;
  /** Epoch ms it was last presented as a review; 0 if never (before 1st review). */
  lastReviewedTs: number;
  /** Epoch ms the current learning cycle began (登録日時). */
  registeredTs: number;
  /** Epoch ms of the last status change. */
  updatedTs: number;
}

const STORAGE_KEY = "typepedia:study";

/** Composite identity. Category folders are space-free ids, so a space is a
 * safe separator between the category and the (arbitrary) typing target. */
function keyOf(category: string, q: string): string {
  return `${category}�${q}`;
}

function readAll(): Record<string, StudyItem> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const data = JSON.parse(raw);
    return data && typeof data === "object"
      ? (data as Record<string, StudyItem>)
      : {};
  } catch {
    return {};
  }
}

function writeAll(map: Record<string, StudyItem>): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(map));
  } catch {
    // Ignore quota / unavailable storage.
  }
}

/** Whether the given question is currently marked 学習中. */
export function isLearning(category: string, q: string): boolean {
  const item = readAll()[keyOf(category, q)];
  return item?.learning ?? false;
}

/**
 * Set the 学習中 flag for a question. Turning it on (re)starts the review
 * cycle — reviews done and last-reviewed time reset so it is immediately due.
 */
export function setLearning(
  category: string,
  sentence: Sentence,
  learning: boolean,
): void {
  const map = readAll();
  const k = keyOf(category, sentence.q);
  const existing = map[k];
  const now = Date.now();
  if (learning) {
    const continuing = existing?.learning ?? false;
    map[k] = {
      category,
      disp: sentence.disp,
      q: sentence.q,
      kana: sentence.kana,
      lang: sentence.lang,
      uuid: sentence.uuid,
      learning: true,
      // Restart the cycle when (re)enabling.
      reviewsDone: continuing ? existing.reviewsDone : 0,
      lastReviewedTs: continuing ? existing.lastReviewedTs : 0,
      registeredTs: continuing ? existing.registeredTs : now,
      updatedTs: now,
    };
  } else if (existing) {
    map[k] = { ...existing, learning: false, updatedTs: now };
  } else {
    // Nothing to record: it was never learning.
    return;
  }
  writeAll(map);
}

/**
 * Effective time of the item's most recent presentation. Before the first
 * review there is none, so the registration time (登録日時) stands in — this is
 * what the 復習頻度 window is measured from for the very first review.
 */
function lastPresentedTs(item: StudyItem): number {
  return item.lastReviewedTs > 0
    ? item.lastReviewedTs
    : (item.registeredTs ?? item.updatedTs);
}

/**
 * Review items in a category that are due now: still learning, not yet
 * graduated (reviewsDone < 復習回数), and past the 復習頻度 window measured from
 * the last presentation (or the registration time before the first review).
 */
export function getDueReviews(
  category: string,
  study: StudySettings,
): StudyItem[] {
  const now = Date.now();
  const freqMs = study.reviewFrequencyHours * 3600_000;
  return Object.values(readAll()).filter(
    (it) =>
      it.category === category &&
      it.learning &&
      it.reviewsDone < study.reviewCount &&
      now - lastPresentedTs(it) >= freqMs,
  );
}

/**
 * The reference info to show when presenting a study item as a review. On the
 * first review there is no prior presentation, so the registration time
 * (登録日時) stands in as the "最終出題日時".
 */
export function reviewInfoOf(item: StudyItem): ReviewInfo {
  return {
    attempt: item.reviewsDone + 1,
    lastReviewedTs: lastPresentedTs(item),
  };
}

/**
 * Record that a review question was completed in a game: bump the count and
 * stamp the presentation time. Once the item has been reviewed 復習回数 times
 * it graduates and 学習中 is cleared automatically. No-op if untracked.
 */
export function recordReview(
  category: string,
  q: string,
  reviewCount: number,
): void {
  const map = readAll();
  const k = keyOf(category, q);
  const item = map[k];
  if (!item) return;
  const now = Date.now();
  const reviewsDone = item.reviewsDone + 1;
  map[k] = {
    ...item,
    reviewsDone,
    lastReviewedTs: now,
    // Auto-graduate out of 学習中 once the review count is reached.
    learning: reviewsDone < reviewCount ? item.learning : false,
    updatedTs: now,
  };
  writeAll(map);
}
